 r.mult+=1;r.dealDisplayMult=r.mult;r.phase='cut';r.stock=deck().filter(c=>!keepIds.has(c.id));r.svetka=null;r.discard=[];r.hands=kept;r.melds=[];r.runClaims=[null,null,null,null];r.ironClaims=[];r.ironSnapshots=[];r.discardEpoch=0;r.allDeclared=[false,false,false,false];r.cardSaid=[false,false,false,false];r.ran=[false,false,false,false];r.turnMeldPoints=[0,0,0,0];r.runReady=[false,false,false,false];r.takenDiscardId=[null,null,null,null];r.reclaimedJokerId=[null,null,null,null];r.pairFinish=[null,null,null,null];r.allTxn=[[],[],[],[]];r.frishVote=null;r.turn=r.dealer;r.drawn=false;
