 if(!o){o=document.createElement('div');o.id='frishVoteOverlay';o.innerHTML='<div id="frishVoteBox"><div id="frishVoteTitle">ФРИШ</div><div class="voteRow"><button id="frishVoteYes">ДА</button><button id="frishVoteNo">НЕТ</button></div></div>';document.body.appendChild(o)}
